# backbutton.py: Android back button and browser Back step back inside KidCog (game -> Play Zone -> activities -> Who's playing).
import base64, hashlib, os, sys
FULL = {'app/App.tsx': ('', '9a128ee94550aff644424cc86b843136'), 'app/src/screens/QuizScreen.tsx': ('', '540d058ef65b88ad88300912451559ab'), 'app/src/screens/PlayZoneScreen.tsx': ('', '6ee4c3d39fc7f44d7cd4c838a8b148ba'), 'app/src/playzone/ArtMusic.tsx': ('', 'd41bcb265f4073bc2db42f9c3dc59a91'), 'app/src/playzone/AnimalExplorer.tsx': ('', '9fc917faedf4cc1c3dd357b200acd651'), 'app/src/playzone/ColoringBook.tsx': ('', 'e833d336a2bb2208f197e3625d870048'), 'app/src/screens/StartScreen.tsx': ('', '80e184df97b186c6975ecb878207fb9d'), 'app/e2e/flows.spec.ts': ('', '0ec28f6c772fdda8aceb28f819b278a9'), 'app/src/backHandler.ts': ('', None)}
for p, (b, orig) in FULL.items():
    if orig is None:
        if os.path.exists(p): sys.exit(p + ' already exists; not applying')
    elif hashlib.md5(open(p, 'rb').read()).hexdigest() != orig:
        sys.exit(p + ' changed since staging; not applying')
for p, (b, _) in FULL.items():
    open(p, 'wb').write(base64.b64decode(b)); print('wrote', p)
